(7, 'Ad1', 'footer_banner', 'code', NULL, '', '<script>\r\n  atOptions = {\r\n    \'key\' : \'feb4076496098cc1c8dd9a5e5b07263a\',\r\n    \'format\' : \'iframe\',\r\n    \'height\' : 90,\r\n    \'width\' : 728,\r\n    \'params\' : {}\r\n  };\r\n</script>\r\n<script src=\"https://www.highrevenueformat.com/feb4076496098cc1c8dd9a5e5b07263a/invoke.js\"></script>', 1, 0, NULL, NULL, NULL, 0, 0, '2026-09-21 09:59:17', '2026-09-21 09:59:17'),
(9, 'Ad1', 'sidebar_top', 'code', NULL, '', '<div class=\"durgapuja-card-2026\" style=\"max-width: 400px; margin: 20px auto; font-family: \'Georgia\', serif; border: 3px double #d4af37; background: radial-gradient(circle, #800000 0%, #4a0000 100%); color: #fff; border-radius: 12px; box-shadow: 0 8px 16px rgba(0,0,0,0.3); overflow: hidden; text-align: center; padding: 25px 20px; position: relative;\">\r\n  <!-- Traditional Border Decor Overlay -->\r\n  <div style=\"font-size: 24px; color: #d4af37; margin-bottom: 10px;\">🔱 ✨ 🔱</div>\r\n  \r\n  <h2 style=\"color: #d4af37; font-size: 28px; margin: 5px 0; text-transform: uppercase; letter-spacing: 1px; font-weight: bold;\">Subho Sharadiya!</h2>\r\n  <h3 style=\"color: #fff; font-size: 18px; margin: 5px 0 15px 0; font-style: italic; opacity: 0.9;\">Happy Durga Puja 2026</h3>\r\n  \r\n  <p style=\"font-size: 15px; line-height: 1.6; color: #f0e6d2; margin: 0 10px 20px 10px; font-family: \'Helvetica Neue\', Arial, sans-serif;\">\r\n    May the divine blessings of Maa Durga bring courage to conquer every obstacle, inner peace, and endless prosperity to your home as the rhythmic beats of the dhak fill the air.\r\n  </p>\r\n  \r\n  <!-- Festival Schedule Tracker -->\r\n  <div style=\"background: rgba(212, 175, 55, 0.15); border-top: 1px solid #d4af37; border-bottom: 1px solid #d4af37; padding: 10px 0; margin-bottom: 15px;\">\r\n    <span style=\"font-size: 12px; text-transform: uppercase; letter-spacing: 2px; color: #d4af37; display: block; margin-bottom: 4px;\">Festive Timeline</span>\r\n    <strong style=\"font-size: 14px; color: #fff; font-family: sans-serif;\">Oct 16 (Shashthi) – Oct 21 (Dashami), 2026</strong>\r\n  </div>\r\n  \r\n  <div style=\"font-size: 11px; opacity: 0.6; font-family: sans-serif; letter-spacing: 0.5px;\">Warm wishes from the Editorial Team</div>\r\n</div>\r\n', 0, 0, NULL, NULL, NULL, 0, 0, '2026-10-02 13:03:16', '2026-10-02 13:08:02'),
(10, 'Ad2', 'sidebar_top', 'code', NULL, '', '<div class=\"mahalaya-embed-container\" style=\"max-width: 600px; margin: 20px auto; font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif; border: 2px solid #d32f2f; border-radius: 12px; background: #fffcf5; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.15);\">\r\n    <div style=\"background: linear-gradient(135deg, #d32f2f 0%, #9a0007 100%); padding: 25px; text-align: center; color: #fff; position: relative;\">\r\n        <span style=\"font-size: 2.2rem; display: block; margin-bottom: 5px; font-weight: bold; letter-spacing: 1px;\">শুভ মহালয়া ২০২৬</span>\r\n        <span style=\"font-size: 0.95rem; opacity: 0.9; text-transform: uppercase; letter-spacing: 2px; display: block; margin-top: 5px;\">Devi Paksha Commences — October 10, 2026</span>\r\n    </div>\r\n    \r\n    <div style=\"padding: 25px;\">\r\n        <div style=\"border-left: 4px solid #ffab00; padding-left: 15px; margin-bottom: 22px;\">\r\n            <p style=\"font-size: 1.15rem; line-height: 1.7; color: #212121; font-weight: 500; margin: 0;\">\"পিতৃপক্ষের অবসানে দেবীপক্ষের পুণ্য লগ্নে, মায়ের আগমনী সুরে ভরে উঠুক সবার জীবন। আগমনীর আনন্দ ছড়িয়ে পড়ুক চারিপাশে।\"</p>\r\n            <span style=\"font-size: 0.95rem; color: #e65100; font-weight: bold; display: block; margin-top: 6px;\">— শুভ মহালয়া ও প্রাক-শারদীয়ার শুভেচ্ছা!</span>\r\n        </div>\r\n\r\n        <div style=\"border-left: 4px solid #ffab00; padding-left: 15px; margin-bottom: 22px;\">\r\n            <p style=\"font-size: 1.15rem; line-height: 1.7; color: #212121; font-weight: 500; margin: 0;\">\"মা দুর্গার আশীর্বাদে দূর হোক আপনার জীবনের সমস্ত অন্ধকার এবং গ্লানি। পরিবারে আসুক সুখ, শান্তি ও অনাবিল সমৃদ্ধি।\"</p>\r\n            <span style=\"font-size: 0.95rem; color: #e65100; font-weight: bold; display: block; margin-top: 6px;\">— দেবীপক্ষের শুভ সূচনা!</span>\r\n        </div>\r\n\r\n        <div style=\"border-left: 4px solid #ffab00; padding-left: 15px; margin-bottom: 5px;\">\r\n            <p style=\"font-size: 1.15rem; line-height: 1.7; color: #212121; font-weight: 500; margin: 0;\">\"শিউলি ফুলের গন্ধ আর ঢাকের কাঠি জানান দিচ্ছে মায়ের আগমন বার্তা। আলোয় আলোকময় হয়ে উঠুক বিশ্ব চরাচর।\"</p>\r\n            <span style=\"font-size: 0.95rem; color: #e65100; font-weight: bold; display: block; margin-top: 6px;\">— শুভ মহালয়া!</span>\r\n        </div>\r\n    </div>\r\n</div>', 0, 0, NULL, NULL, NULL, 0, 0, '2026-10-02 13:06:57', '2026-10-13 16:06:34'),
(14, 'ads3', 'sidebar_top', 'code', NULL, '', '<!-- Senco Gold & Diamonds Advertisement -->\r\n<div class=\"senco-ad-container\"\r\n     style=\"text-align:center; margin:20px auto; max-width:728px;\">\r\n\r\n  <a href=\"https://sencogoldanddiamonds.com/\"\r\n     target=\"_blank\"\r\n     rel=\"noopener noreferrer\"\r\n     title=\"Shop Senco Gold & Diamonds\">\r\n\r\n    <img\r\n      src=\"https://sencowebfiles.s3.ap-south-1.amazonaws.com/cms/banners/5d1c9eba-13a7-4617-aedb-6cb928c6ff7c.jpg\"\r\n      alt=\"Senco Gold & Diamonds Jewellery Collection\"\r\n      style=\"display:block; width:100%; height:auto; border:1px solid #ddd; box-shadow:0 4px 6px rgba(0,0,0,0.1);\"\r\n      loading=\"lazy\"\r\n    />\r\n\r\n  </a>\r\n\r\n</div>', 1, 0, '2026-10-13', '2026-10-18', NULL, 0, 0, '2026-10-13 17:05:57', '2026-10-13 17:10:39');

